    {
      "id": 1,
      "claim": "Mastery in a sport is defined as expert‑level skill and sustained high performance, typically measured by competition level, ranking, or validated proficiency benchmarks.",
      "evidence": "Sport‑science literature on expertise (e.g., Ericsson et al., 1993; WHO definition of elite athletes).",
      "weight": 0.12,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "\"Smarter in school\" refers to measurable academic outcomes such as higher grades, standardized test scores, or improved classroom performance.",
      "evidence": "Educational assessment standards (e.g., OECD PISA framework, U.S. Common Core State Standards).",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Observational studies consistently report a positive correlation between regular physical activity and better academic performance.",
      "evidence": "Meta‑analysis of school‑based physical‑activity programs (Singh et al., 2012) showing modest effect sizes.",
      "weight": 0.18,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Correlation does not imply causation; the observed link can be explained by confounding variables such as socioeconomic status, motivation, or overall health.",
      "evidence": "Epidemiological principle and critiques highlighting confounders (Bailey et al., 2015).",
      "weight": 0.20,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Experimental evidence that isolates sport‑mastery (as opposed to general exercise) as the causal factor for academic improvement is scarce or absent.",
      "evidence": "Systematic reviews noting a lack of randomized controlled trials testing sport‑mastery interventions (Donnelly & Lambourne, 2011).",
      "weight": 0.22,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Scientific consensus therefore states that there is insufficient evidence to claim that achieving mastery in a sport makes students smarter in school.",
      "evidence": "Position statements from the American College of Sports Medicine (2020) and educational‑psychology bodies emphasizing the need for robust causal data.",
      "weight": 0.13,
      "depends_on": [5]
    }
  ],
  "answer": "D",
  "confidence": 0.85,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Implies a direct causal benefit of sport mastery on academics, which is not supported by strong evidence."
    },
    {
      "answer": "B",
      "reason_rejected": "Assumes a general intelligence link between being smart and being good at sports, lacking empirical support."
    },
    {
      "answer": "C",
      "reason_rejected": "States a direct causal mechanism (sport mastery → smarter) that the literature does not substantiate."
    }
  ]
